cssCode:
.glitch-text {
  font-size: 32px; font-weight: 900;
  color: #fff; position: relative;
  font-family: monospace; letter-spacing: 2px;
  cursor: pointer;
}
.glitch-text::before, .glitch-text::after {
  content: attr(data-text); position: absolute;
  top: 0; left: 0; width: 100%; height: 100%;
  opacity: 0;
}
.glitch-text:active::before, .glitch-text:hover::before {
  left: 3px; text-shadow: -2px 0 #ff00c1;
  clip-path: polygon(0 20%, 100% 20%, 100% 40%, 0 40%);
  animation: glitchAnim 0.3s infinite linear alternate-reverse; opacity: 1;
}
.glitch-text:active::after, .glitch-text:hover::after {
  left: -3px; text-shadow: -2px 0 #00fff9;
  clip-path: polygon(0 60%, 100% 60%, 100% 80%, 0 80%);
  animation: glitchAnim 0.2s infinite linear alternate-reverse; opacity: 1;
}
@keyframes glitchAnim {
  0% { transform: translate(0); }
  100% { transform: translate(-3px, 2px); }
}

